'use strict';
(()=>{
 let scene,camera,renderer,root,canvas,road,finish,world,players=[],markers=[],scenery=[],state=null,last=0,scroll=0,shape='',failed=false;
 const project=new THREE.Vector3();
 function mesh(geometry,material,x=0,y=0,z=0){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);return m}
 const box=(w,h,d,mat,x,y,z)=>mesh(new THREE.BoxGeometry(w,h,d),mat,x,y,z);
 function material(c,metal=.3,rough=.4){return new THREE.MeshStandardMaterial({color:c,metalness:metal,roughness:rough})}
 function createCar(style,index){const group=new THREE.Group(),paint=material(style.color,.65,.26),dark=material('#07101a',.45,.35),glass=material('#48adc8',.8,.15),silver=material('#c6d9e6',.85,.2);const model=style.model||'gt';
  group.add(box(1.48,.36,2.8,paint,0,.48,0),box(1.23,.18,1.1,paint,0,.69,-.85));
  group.add(box(model==='formula'?.65:1.08,.42,model==='rally'?1.25:1.0,glass,0,.85,.18));
  group.add(box(.15,.03,2.4,silver,0,.69,-.08));
  const tires=[];for(const x of [-.85,.85])for(const z of [-.85,.9]){const tire=mesh(new THREE.CylinderGeometry(.37,.37,.32,12),dark,x,.36,z);tire.rotation.z=Math.PI/2;group.add(tire);const rim=mesh(new THREE.CylinderGeometry(.19,.19,.335,8),silver,x,.36,z);rim.rotation.z=Math.PI/2;group.add(rim);tires.push(tire,rim)}
  if(model==='formula'){group.add(box(1.9,.12,.36,paint,0,.37,-1.48),box(1.9,.13,.45,paint,0,1.05,1.28));for(const x of [-.6,.6])group.add(box(.08,.45,.1,dark,x,.85,1.27))}else{group.add(box(1.7,.1,.35,dark,0,.95,1.3));for(const x of [-.6,.6])group.add(box(.08,.4,.1,dark,x,.76,1.25))}
  const tail=new THREE.MeshBasicMaterial({color:'#ff375d'}),head=new THREE.MeshBasicMaterial({color:'#e2ffff'});for(const x of [-.5,.5]){group.add(box(.3,.13,.04,tail,x,.59,1.42));group.add(box(.28,.13,.04,head,x,.57,-1.42))}
  const glow=mesh(new THREE.PlaneGeometry(2.2,3.8),new THREE.MeshBasicMaterial({color:style.color,transparent:true,opacity:.15,depthWrite:false}),0,.025,.3);glow.rotation.x=-Math.PI/2;group.add(glow);
  const shadow=mesh(new THREE.PlaneGeometry(2,3.3),new THREE.MeshBasicMaterial({color:'#000000',transparent:true,opacity:.5,depthWrite:false}),0,.03,.1);shadow.rotation.x=-Math.PI/2;group.add(shadow);
  const label=document.createElement('div');label.className='race3d-profile';label.style.setProperty('--car',style.color);label.innerHTML='<span class="race3d-number"></span><img alt=""><span class="race3d-initial"></span><span class="race3d-flag"></span>';root.append(label);
  group.scale.setScalar(1.25);return {group,paint,tires,label,index,distance:null,velocity:0,key:''};
 }
 function init(){if(failed||renderer)return !!renderer;try{root=document.createElement('div');root.id='race3d';root.setAttribute('aria-label','Three-dimensional car race');document.getElementById('track').append(root);renderer=new THREE.WebGLRenderer({alpha:false,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;canvas=renderer.domElement;root.prepend(canvas);scene=new THREE.Scene();scene.background=new THREE.Color('#071629');scene.fog=new THREE.Fog('#071629',35,135);camera=new THREE.PerspectiveCamera(48,1,.1,220);scene.add(new THREE.HemisphereLight('#b6e8ff','#27363d',2.4));const sun=new THREE.DirectionalLight('#fff2da',3);sun.position.set(-8,18,12);scene.add(sun);world=new THREE.Group();scene.add(world);document.body.classList.add('scene3d-active');canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();document.body.classList.remove('scene3d-active')});requestAnimationFrame(draw);return true}catch(e){failed=true;root?.remove();document.body.classList.remove('scene3d-active');return false}}
 function dispose(object){object.traverse(o=>{o.geometry?.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material?.dispose()})}
 function rebuild(){players.forEach(p=>{p.label.remove();dispose(p.group);scene.remove(p.group)});players=[];dispose(world);world.clear();markers=[];scenery=[];const count=state.settings.cars,width=count*3.2+1.4;
  road=box(width,.18,200,material('#172332',.05,.92),0,-.12,-75);world.add(road);world.add(box(300,.1,230,material('#102b33',.1,1),0,-.3,-75));
  for(const side of [-1,1]){const x=side*(width/2+.2);world.add(box(.3,.45,200,material('#7addf1',.65,.3),x,.16,-75));for(let z=10;z>-160;z-=7){const p=box(.35,.28,2.1,material(z%2?'#eaeff0':'#ef5475',.15,.55),x,.43,z);world.add(p);scenery.push({mesh:p,start:z,range:170})}}
  const white=new THREE.MeshBasicMaterial({color:'#b4d8e3'});for(let lane=1;lane<count;lane++){const x=(lane-count/2)*3.2;for(let z=10;z>-150;z-=7){const p=box(.10,.015,3.1,white,x,.02,z);world.add(p);markers.push({mesh:p,start:z,range:160})}}
  for(let z=6;z>-140;z-=12)for(const side of [-1,1]){const pole=box(.12,3,.12,material('#4a6578',.6,.4),side*(width/2+1.3),1.5,z);world.add(pole);const light=box(.9,.12,.25,new THREE.MeshBasicMaterial({color:'#55dbff'}),side*(width/2+1.1),3,z);world.add(light);scenery.push({mesh:pole,start:z,range:148},{mesh:light,start:z,range:148});const building=box(3,5+(Math.abs(z)%13),4,material(side<0?'#123b53':'#284665',.35,.5),side*(width/2+5),2,z-7);world.add(building);scenery.push({mesh:building,start:z-7,range:148})}
  finish=new THREE.Group();const black=new THREE.MeshBasicMaterial({color:'#06101c'}),check=new THREE.MeshBasicMaterial({color:'#f0fcff'});for(let row=0;row<2;row++)for(let x=0;x<count*4;x++){const size=width/(count*4);finish.add(box(size,.02,.65,(x+row)%2?black:check,-width/2+(x+.5)*size,.04,row*.65-.4))}finish.position.z=-31;world.add(finish);
  for(let i=0;i<count;i++){const style=state.carStyles?.[i]||{color:['#ffc857','#58d9ff','#ff5c83','#71edb1','#bf94ff'][i],model:'gt'};const p=createCar(style,i);p.group.position.x=(i-(count-1)/2)*3.2;scene.add(p.group);players.push(p)}
 }
 function resize(){if(!renderer)return;const parent=document.getElementById('track'),roadElement=parent.querySelector('.road');if(!roadElement)return;const bounds=parent.getBoundingClientRect(),r=roadElement.getBoundingClientRect(),width=bounds.width,height=r.height;if(!width||!height)return;root.style.top=(r.top-bounds.top)+'px';root.style.height=height+'px';if(canvas.clientWidth!==Math.round(width)||canvas.clientHeight!==Math.round(height))renderer.setSize(width,height);camera.aspect=width/height;camera.position.set(0,camera.aspect>1.4?10:12,camera.aspect>1.4?18:22);camera.lookAt(0,0,-12);camera.updateProjectionMatrix()}
 function update(r){state=r;if(!document.body.classList.contains('screen')||!init())return;const next=JSON.stringify([r.settings.cars,r.carStyles]);if(next!==shape){shape=next;rebuild()}for(const [i,p]of players.entries()){const driver=r.slots[i],key=JSON.stringify([driver?.id,driver?.avatar,driver?.name,driver?.countryFlag]);if(key!==p.key){p.key=key;p.label.querySelector('.race3d-number').textContent=String(i+1);const img=p.label.querySelector('img');img.hidden=!driver?.avatar;if(driver?.avatar)img.src=driver.avatar;p.label.querySelector('.race3d-initial').textContent=driver?.avatar?'':(driver?.name||'CAR').slice(0,1);p.label.querySelector('.race3d-flag').textContent=driver?.countryFlag||'';p.label.title=driver?.name||'OPEN SLOT'}p.group.visible=!!driver;p.label.hidden=!driver}resize()}
 function draw(t){requestAnimationFrame(draw);if(!state||!renderer)return;const dt=Math.min(.06,Math.max(.001,(t-last)/1000||.016));last=t;const running=state.settings.running&&!state.settings.paused&&state.winner===null&&Date.now()>=state.startsAt-(window.__raceServerOffset||0);let speed=0;
  for(const [i,p]of players.entries()){const driver=state.slots[i];if(!driver)continue;const target=driver.distance||0;if(p.distance===null||state.round!==p.round){p.distance=target;p.round=state.round}const before=p.distance;p.distance+=(target-p.distance)*(1-Math.exp(-dt*10));const velocity=Math.max(0,(p.distance-before)/dt);p.velocity+=(velocity-p.velocity)*(1-Math.exp(-dt*4));speed=Math.max(speed,p.velocity);const fraction=p.distance/state.settings.length;p.group.position.z=5-fraction*36;p.group.position.y=running?Math.sin(t*.025+i)*Math.min(.025,p.velocity*.002):0;p.group.rotation.z=running?Math.sin(t*.004+i)*.012:0;for(const tire of p.tires)tire.rotation.x-=running?dt*(5+p.velocity):0;
   project.set(p.group.position.x,2.0,p.group.position.z+.5).project(camera);const scale=Math.max(.55,Math.min(1.25,1.1-fraction*.35));p.label.style.transform=`translate(-50%,-50%) scale(${scale})`;p.label.style.left=(project.x*.5+.5)*root.clientWidth+'px';p.label.style.top=(-project.y*.5+.5)*root.clientHeight+'px';
  }
  if(running)scroll=(scroll+dt*(12+Math.min(40,speed*.6)))%10000;for(const p of [...markers,...scenery])p.mesh.position.z=((p.start+scroll+160)%p.range)-p.range+12;
  finish.position.z=-31;if(state.winner!==null)finish.position.z=-31;resize();renderer.render(scene,camera);
 }
 window.Race3D={update,resize,get renderer(){return renderer},get players(){return players}};window.addEventListener('resize',resize);
})();
